def mri_nl_align_outputs(params: MriNlAlign, execution: Execution) -> MriNlAlignOutputs:
    """Build the MriNlAlignOutputs object for this tool."""
    root_v: OutputPathType = execution.output_file(".")
    warp_output_v: OutputPathType = execution.output_file(params["warp"])
    return MriNlAlignOutputs(
        root=root_v,
        warp_output=warp_output_v,
    )

def mri_nl_align_execute(params: MriNlAlign, runner: Runner | None = None) -> MriNlAlignOutputs:
    """
    mri_nl_align

    mri_nl_align aligns two images using nonlinear registration.

    Author: FreeSurfer Developers

    URL: https://github.com/freesurfer/freesurfer

    Args:
        params: The parameters.
        runner: Command runner (defaults to global runner).

    Returns:
        Tool outputs (paths to files produced by the tool).
    """
    mri_nl_align_validate(params)
    runner = runner if runner is not None else get_global_runner()
    execution = runner.start_execution(MRI_NL_ALIGN_METADATA)
    execution.params(params)
    args = mri_nl_align_cargs(params, execution)
    out = mri_nl_align_outputs(params, execution)
    execution.run(args)
    return out

